1	import {
2	  FOLDER_OVERRIDE_KEYS,
3	  isOverridableKey,
4	  type CopyToAllResult,
5	  type FolderOverrideKey,
6	  type FolderOverridesState,
7	  type OverridableKey,
8	  type ResetOverridesResult,
9	  type ResolvePendingResult,
10	  type ScopedSettings,
11	  type SetOverrideResult,
12	  type SettingsOverrides,
13	} from "@shared/settings-scope";
14	import type { AppSettings } from "@shared/types";
15	import {
16	  type FolderOverrides,
17	  type FolderRead,
18	  type MachineSettingsStore,
19	  folderState,
20	  normalizeOverride,
21	  readFolderOverrides,
22	  resolveEffective,
23	  writeFolderOverrides,
24	} from "./settings-overrides";
25	
26	/** How long a capture waits for a folder file before it counts as unreadable (an evicted file). */
27	const READ_TIMEOUT_MS = 2000;
28	
29	export interface WorkspaceSettingsDeps {
30	  machine: MachineSettingsStore;
31	  /** The registered workspaces (id, name, folder). */
32	  workspaces(): ReadonlyArray<{ id: string; name: string; path: string }>;
33	  activeId(): string;
34	  /** Whether the workspace's folder is reachable right now. */
35	  isAvailable(id: string): Promise<boolean>;
36	  /** The persisted All workspaces level. */
37	  getAll(): AppSettings;
38	  /** Write values to the All workspaces level. */
39	  writeAll(patch: Partial<AppSettings>): void;
40	  /** The active workspace's effective settings (what every snapshot carries). */
41	  effective(): AppSettings;
42	  /** The active workspace's effective settings may have changed: recompute and tell everyone. */
43	  changed(): void;
44	  now(): number;
45	  readTimeoutMs?: number;
46	}
47	
48	type Changes = Partial<Record<OverridableKey, unknown>>;
49	
50	/**
51	 * Per-workspace setting overrides (ADR 0034): the resolver's source of truth for the active
52	 * workspace, the writes behind `settings:set-override` / `resolve-pending`, and the scoped read
53	 * the Settings page uses. Folder files are read into a cache at the moments the ADR names (a
54	 * workspace added or activated, app start, each capture start), so the effective settings can
55	 * be asked for synchronously from anywhere.
56	 */
57	export class WorkspaceSettings {
58	  private readonly reads = new Map<string, FolderRead>();
59	  /** The last read that actually saw the file (present or absent): what an unplugged drive held. */
60	  private readonly lastSeen = new Map<string, FolderRead>();
61	  /** The last write of each workspace: read → write → record must not interleave with itself. */
62	  private readonly queues = new Map<string, Promise<unknown>>();
63	
64	  constructor(private readonly deps: WorkspaceSettingsDeps) {}
65	
66	  /**
67	   * Bumped before and after every write of a workspace's folder file, so a read that began before
68	   * the write ended may hold the old bytes. Together with `writing` (a write in flight) and
69	   * `refreshTickets` (the refresh that started last wins) it keeps a slow or overlapping refresh
70	   * from putting an older read, with the old sha256, over what this Mac just recorded.
71	   */
72	  private readonly writeEpochs = new Map<string, number>();
73	  private readonly writing = new Map<string, number>();
74	  private readonly refreshTickets = new Map<string, number>();
75	  private readonly refreshApplied = new Map<string, number>();
76	  /**
77	   * The overrides as they were when a write began. While the write runs the new hash is already
78	   * recorded and the file still holds the old bytes; reading the cache against that record would
79	   * switch this Mac's own overrides off for a moment, so the answer is held until it ends.
80	   */
81	  private readonly frozen = new Map<string, SettingsOverrides>();
82	
83	  /**
84	   * A fresh read taken on the write path (an answer, or the read an edit starts from) is newer
85	   * than any refresh already in flight: bumping the epoch makes those drop what they read.
86	   */
87	  private fence(id: string): void {
88	    this.writeEpochs.set(id, (this.writeEpochs.get(id) ?? 0) + 1);
89	  }
90	
91	  private beginWrite(id: string): void {
92	    this.frozen.set(id, this.computeOverrides(id));
93	    this.writing.set(id, (this.writing.get(id) ?? 0) + 1);
94	    this.writeEpochs.set(id, (this.writeEpochs.get(id) ?? 0) + 1);
95	  }
96	
97	  private endWrite(id: string): void {
98	    this.frozen.delete(id);
99	    this.writing.set(id, Math.max(0, (this.writing.get(id) ?? 1) - 1));
100	    this.writeEpochs.set(id, (this.writeEpochs.get(id) ?? 0) + 1);
101	  }
102	
103	  private remember(id: string, read: FolderRead): void {
104	    this.reads.set(id, read);
105	    if (read.kind !== "unreadable") this.lastSeen.set(id, read);
106	  }
107	
108	  /** Run `job` after every earlier write of the same workspace; a failure does not block the next. */
109	  private serialize<T>(id: string, job: () => Promise<T>): Promise<T> {
110	    const run = (this.queues.get(id) ?? Promise.resolve()).then(job);
111	    const tail = run.catch(() => undefined);
112	    this.queues.set(id, tail);
113	    void tail.then(() => {
114	      if (this.queues.get(id) === tail) this.queues.delete(id);
115	    });
116	    return run;
117	  }
118	
119	  private known(id: string): { id: string; name: string; path: string } | undefined {
120	    return this.deps.workspaces().find((ws) => ws.id === id);
121	  }
122	
123	  private async read(path: string): Promise<FolderRead> {
124	    const timeout = this.deps.readTimeoutMs ?? READ_TIMEOUT_MS;
125	    let timer: ReturnType<typeof setTimeout> | undefined;
126	    try {
127	      return await Promise.race([
128	        readFolderOverrides(path),
129	        new Promise<FolderRead>((resolve) => {
130	          timer = setTimeout(() => resolve({ kind: "unreadable" }), timeout);
131	        }),
132	      ]);
133	    } catch {
134	      return { kind: "unreadable" };
135	    } finally {
136	      clearTimeout(timer);
137	    }
138	  }
139	
140	  /**
141	   * Read a workspace's folder file into the cache. A workspace that is not connected has no
142	   * readable file. When the active workspace's overrides change because of it (a sync wrote
143	   * the file), everyone is told.
144	   */
145	  async refresh(id: string): Promise<void> {
146	    const ws = this.known(id);
147	    if (!ws) return;
148	    const before = JSON.stringify(this.overridesOf(id));
149	    const epoch = this.writeEpochs.get(id) ?? 0;
150	    const ticket = (this.refreshTickets.get(id) ?? 0) + 1;
151	    this.refreshTickets.set(id, ticket);
152	    const read = await this.probe(id, ws.path);
153	    // A write is under way, or ended while this file was read: the read may predate it, and the
154	    // write has the newer say. A refresh that started after this one has too.
155	    if ((this.writing.get(id) ?? 0) > 0 || (this.writeEpochs.get(id) ?? 0) !== epoch) return;
156	    if (ticket < (this.refreshApplied.get(id) ?? 0)) return;
157	    this.refreshApplied.set(id, ticket);
158	    this.remember(id, read);
159	    if (id === this.deps.activeId() && before !== JSON.stringify(this.overridesOf(id))) {
160	      this.deps.changed();
161	    }
162	  }
163	
164	  /**
165	   * The folder file as it reads now. The WHOLE probe is bounded (is the folder reachable, then
166	   * the read): a capture waits on this, and an unreachable or evicted folder must not hold the
167	   * overlay back. A probe that runs out of time counts as an unreadable file.
168	   */
169	  private async probe(id: string, path: string): Promise<FolderRead> {
170	    const timeout = this.deps.readTimeoutMs ?? READ_TIMEOUT_MS;
171	    let timer: ReturnType<typeof setTimeout> | undefined;
172	    try {
173	      return await Promise.race([
174	        (async (): Promise<FolderRead> =>
175	          (await this.deps.isAvailable(id)) ? await this.read(path) : { kind: "unreadable" })(),
176	        new Promise<FolderRead>((resolve) => {
177	          timer = setTimeout(() => resolve({ kind: "unreadable" }), timeout);
178	        }),
179	      ]);
180	    } catch {
181	      return { kind: "unreadable" };
182	    } finally {
183	      clearTimeout(timer);
184	    }
185	  }
186	
187	  private stateOf(id: string): Exclude<FolderOverridesState, "unavailable"> {
188	    const read = this.reads.get(id) ?? { kind: "absent" as const };
189	    return folderState(read, this.deps.machine.get(id).folderOverrides);
190	  }
191	
192	  /** The overrides that apply in a workspace: its confirmed folder file plus its machine-bound mode. */
193	  private overridesOf(id: string): SettingsOverrides {
194	    const held = this.frozen.get(id);
195	    if (held) return held;
196	    return this.computeOverrides(id);
197	  }
198	
199	  private computeOverrides(id: string): SettingsOverrides {
200	    const overrides: SettingsOverrides = {};
201	    const read = this.reads.get(id);
202	    if (this.stateOf(id) === "active" && read?.kind === "ok")
203	      Object.assign(overrides, read.overrides);
204	    const uploadMode = this.deps.machine.get(id).uploadMode;
205	    if (uploadMode) overrides.uploadMode = uploadMode;
206	    return overrides;
207	  }
208	
209	  /** The active workspace's overrides, answered from the cache. */
210	  activeOverrides(): SettingsOverrides {
211	    return this.overridesOf(this.deps.activeId());
212	  }
213	
214	  async getScoped(scope: string): Promise<ScopedSettings> {
215	    const all = this.deps.getAll();
216	    if (scope === "all") {
217	      const overriddenIn: Partial<Record<OverridableKey, string[]>> = {};
218	      for (const ws of this.deps.workspaces()) {
219	        await this.refresh(ws.id);
220	        for (const key of Object.keys(this.overridesOf(ws.id)) as OverridableKey[]) {
221	          (overriddenIn[key] ??= []).push(ws.name);
222	        }
223	      }
224	      return {
225	        scope,
226	        all,
227	        overrides: {},
228	        effective: all,
229	        folder: "none",
230	        pending: null,
231	        folderSha256: null,
232	        overriddenIn,
233	      };
234	    }
235	    if (!this.known(scope)) {
236	      return {
237	        scope,
238	        all,
239	        overrides: {},
240	        effective: all,
241	        folder: "unavailable",
242	        pending: null,
243	        folderSha256: null,
244	        overriddenIn: {},
245	      };
246	    }
247	    const available = await this.deps.isAvailable(scope);
248	    await this.refresh(scope);
249	    const overrides = this.overridesOf(scope);
250	    const read = this.reads.get(scope);
251	    const state = available ? this.stateOf(scope) : "unavailable";
252	    const waiting = (state === "pending" || state === "ignored") && read?.kind === "ok";
253	    return {
254	      scope,
255	      all,
256	      overrides,
257	      effective: resolveEffective(all, overrides),
258	      folder: state,
259	      pending: waiting ? read.overrides : null,
260	      folderSha256: waiting ? read.sha256 : null,
261	      overriddenIn: {},
262	    };
263	  }
264	
265	  /**
266	   * Apply a set of changes to one workspace (`null` removes a key). Folder keys go to the
267	   * folder file in a single write, `uploadMode` to the machine file. Nothing is written when
268	   * nothing would change.
269	   */
270	  private apply(id: string, changes: Changes): Promise<SetOverrideResult> {
271	    return this.serialize(id, () => this.applyNow(id, changes));
272	  }
273	
274	  private async applyNow(id: string, changes: Changes): Promise<SetOverrideResult> {
275	    const ws = this.known(id);
276	    if (!ws) return { ok: false, reason: "unknown-workspace" };
277	    const checked: Changes = {};
278	    for (const [key, value] of Object.entries(changes)) {
279	      if (!isOverridableKey(key)) return { ok: false, reason: "not-overridable" };
280	      if (value === null) {
281	        checked[key] = null;
282	        continue;
283	      }
284	      const normalized = normalizeOverride(key, value);
285	      if (!normalized.ok) return { ok: false, reason: "invalid" };
286	      checked[key] = normalized.value;
287	    }
288	    if (!(await this.deps.isAvailable(id))) return { ok: false, reason: "unavailable" };
289	
290	    const folderKeys = Object.keys(checked).filter((key): key is FolderOverrideKey =>
291	      (FOLDER_OVERRIDE_KEYS as readonly string[]).includes(key),
292	    );
293	    try {
294	      // The machine-bound key does not depend on the folder file, so a pending or unreadable
295	      // file never keeps it from changing.
296	      if ("uploadMode" in checked) {
297	        const next = checked["uploadMode"];
298	        await this.deps.machine.update(id, (entry) => {
299	          const { uploadMode: _drop, ...rest } = entry;
300	          void _drop;
301	          return next === null ? rest : { ...rest, uploadMode: next as AppSettings["uploadMode"] };
302	        });
303	      }
304	      if (folderKeys.length > 0) {
305	        const refused = await this.applyFolder(ws, folderKeys, checked);
306	        if (refused) {
307	          this.deps.changed();
308	          return { ok: false, reason: refused };
309	        }
310	      }
311	    } catch (error) {
312	      console.error("[workspace-settings] write failed", error);
313	      this.deps.changed();
314	      return { ok: false, reason: "failed" };
315	    }
316	    this.deps.changed();
317	    return { ok: true, settings: this.deps.effective() };
318	  }
319	
320	  private async applyFolder(
321	    ws: { id: string; path: string },
322	    keys: FolderOverrideKey[],
323	    changes: Changes,
324	  ): Promise<"pending" | "unreadable" | null> {
325	    // Always from the disk: the cache may predate a sync.
326	    const read = await this.read(ws.path);
327	    this.remember(ws.id, read);
328	    this.fence(ws.id);
329	    const state = folderState(read, this.deps.machine.get(ws.id).folderOverrides);
330	    if (state === "unreadable") return "unreadable";
331	    // The user has not seen these values: writing now would activate them by the back door.
332	    if (state === "pending") return "pending";
333	    // An ignored file is replaced by the keys this Mac now writes (spec, decision 26).
334	    const base: FolderOverrides = state === "active" && read.kind === "ok" ? read.overrides : {};
335	    const next: Record<string, unknown> = { ...base };
336	    for (const key of keys) {
337	      if (changes[key] === null) delete next[key];
338	      else next[key] = changes[key];
339	    }
340	    const unchanged =
341	      JSON.stringify(next) === JSON.stringify(base) &&
342	      (state === "active" || Object.keys(next).length === 0);
343	    if (unchanged) return null;
344	    const previous = this.deps.machine.get(ws.id).folderOverrides;
345	    let sha256: string;
346	    this.beginWrite(ws.id);
347	    try {
348	      // The new hash is recorded BEFORE the file changes (see `writeFolderOverrides`), so this
349	      // Mac's own edit is never mistaken for a change made by a sync.
350	      sha256 = await writeFolderOverrides(ws.path, next as FolderOverrides, (hash) =>
351	        this.deps.machine.update(ws.id, (entry) => ({
352	          ...entry,
353	          folderOverrides: { sha256: hash, decision: "use", at: this.deps.now() },
354	        })),
355	      );
356	    } catch (error) {
357	      // The file did not change: put the record of the file that is still there back.
358	      await this.deps.machine
359	        .update(ws.id, ({ folderOverrides: _drop, ...rest }) => {
360	          void _drop;
361	          return previous ? { ...rest, folderOverrides: previous } : rest;
362	        })
363	        .catch(() => undefined);
364	      this.endWrite(ws.id);
365	      throw error;
366	    }
367	    this.remember(ws.id, { kind: "ok", overrides: next as FolderOverrides, sha256 });
368	    this.endWrite(ws.id);
369	    return null;
370	  }
371	
372	  setOverride(id: string, key: OverridableKey, value: unknown | null): Promise<SetOverrideResult> {
373	    if (!isOverridableKey(key)) return Promise.resolve({ ok: false, reason: "not-overridable" });
374	    return this.apply(id, { [key]: value });
375	  }
376	
377	  resetOverrides(id: string, keys: readonly OverridableKey[]): Promise<ResetOverridesResult> {
378	    const changes: Changes = {};
379	    for (const key of keys) changes[key] = null;
380	    return this.apply(id, changes);
381	  }
382	
383	  /**
384	   * "Use them" / "Ignore" for a folder file (ADR 0034, decision 8). `sha256` names the file the
385	   * user saw: a file that changed since is not confirmed by an answer meant for the old one.
386	   */
387	  resolvePending(
388	    id: string,
389	    decision: "use" | "ignore",
390	    sha256: string,
391	  ): Promise<ResolvePendingResult> {
392	    return this.serialize(id, () => this.resolvePendingNow(id, decision, sha256));
393	  }
394	
395	  private async resolvePendingNow(
396	    id: string,
397	    decision: "use" | "ignore",
398	    sha256: string,
399	  ): Promise<ResolvePendingResult> {
400	    const ws = this.known(id);
401	    if (!ws) return { ok: false, reason: "unknown-workspace" };
402	    if (!(await this.deps.isAvailable(id))) return { ok: false, reason: "nothing-pending" };
403	    const read = await this.read(ws.path);
404	    this.remember(id, read);
405	    this.fence(id);
406	    const state = folderState(read, this.deps.machine.get(id).folderOverrides);
407	    if (read.kind !== "ok" || state === "none" || state === "unreadable") {
408	      this.deps.changed();
409	      return { ok: false, reason: "nothing-pending" };
410	    }
411	    if (read.sha256 !== sha256) {
412	      this.deps.changed();
413	      return { ok: false, reason: "changed" };
414	    }
415	    try {
416	      await this.deps.machine.update(id, (entry) => ({
417	        ...entry,
418	        folderOverrides: { sha256: read.sha256, decision, at: this.deps.now() },
419	      }));
420	    } catch (error) {
421	      console.error("[workspace-settings] recording the answer failed", error);
422	      return { ok: false, reason: "failed" };
423	    }
424	    this.deps.changed();
425	    return { ok: true, settings: this.deps.effective() };
426	  }
427	
428	  /**
429	   * Whether a workspace whose override could not be cleared may still hold one of `keys`: its
430	   * machine-bound upload mode, the valid entries of its last read file, or, with no read at all,
431	   * the honest "cannot rule it out".
432	   */
433	  private mayHoldOwn(id: string, keys: readonly OverridableKey[]): boolean {
434	    if (keys.includes("uploadMode") && this.deps.machine.get(id).uploadMode) return true;
435	    const read = this.lastSeen.get(id);
436	    // Never seen: nothing rules it out.
437	    if (!read) return true;
438	    if (read.kind === "absent") return false;
439	    return read.kind === "ok" && keys.some((key) => key in read.overrides);
440	  }
441	
442	  /**
443	   * "Copy to all workspaces": the value `id` shows becomes the All level's, and every workspace
444	   * drops its own override of the key, so all of them inherit it and cannot drift apart later.
445	   * A workspace whose override cannot be cleared (not connected, unreadable file, an answer
446	   * still pending) keeps it and is named in `keptOwn`, because "all" must not quietly mean
447	   * "all that were connected".
448	   */
449	  async copyToAll(id: string, keys: readonly OverridableKey[]): Promise<CopyToAllResult> {
450	    if (!this.known(id)) return { ok: false, reason: "unknown-workspace" };
451	    if (!keys.every(isOverridableKey)) return { ok: false, reason: "not-overridable" };
452	    // A workspace that is not connected cannot say what it shows: nothing is copied from it.
453	    if (!(await this.deps.isAvailable(id))) return { ok: false, reason: "unavailable" };
454	    const wanted = [...new Set(keys)];
455	    await this.refresh(id);
456	    // A file that cannot be read cannot say what the workspace shows: refuse before any write.
457	    // (`uploadMode` is machine-bound, so an unreadable folder file does not stop it.)
458	    if (wanted.some((key) => key !== "uploadMode") && this.reads.get(id)?.kind === "unreadable") {
459	      return { ok: false, reason: "unreadable" };
460	    }
461	    const shown = resolveEffective(this.deps.getAll(), this.overridesOf(id));
462	    const patch: Record<string, unknown> = {};
463	    for (const key of wanted) patch[key] = shown[key];
464	    try {
465	      this.deps.writeAll(patch as Partial<AppSettings>);
466	    } catch (error) {
467	      console.error("[workspace-settings] writing the All level failed", error);
468	      return { ok: false, reason: "failed" };
469	    }
470	    const keptOwn: string[] = [];
471	    for (const ws of this.deps.workspaces()) {
472	      const result = await this.resetOverrides(ws.id, wanted);
473	      if (result.ok) continue;
474	      // Named only when it really keeps a value of its own for one of the copied keys.
475	      if (this.mayHoldOwn(ws.id, wanted)) keptOwn.push(ws.name);
476	    }
477	    this.deps.changed();
478	    return { ok: true, settings: this.deps.effective(), keptOwn };
479	  }
480	}
